#include <algorithm>

using namespace std;

int pref[26][100005];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    string s;
    cin >> s;

    for (int i = 0; i < n; ++i) {
        for (int c = 0; c < 26; ++c) {
            pref[c][i + 1] = pref[c][i];
        }
        pref[s[i] - 'a'][i + 1]++;
    }

    vector<int> divisors;
    for (int i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            divisors.push_back(i);
            if (i * i != n && i != 1) {
                divisors.push_back(n / i);
            }
        }
    }
    // Remove n itself if it was added (only happens if i=1, but we didn't add n/1 above, wait:
    // for i = 1, divisors has 1. n/1 is n, which is not added because i == 1.
    // What if n is square and i*i == n? It's added once.
    // So all divisors < n are collected.

    sort(divisors.begin(), divisors.end());

    int target[26];
    for (int L : divisors) {
        for (int c = 0; c < 26; ++c) {
            target[c] = pref[c][L];
        }

        bool ok = true;
        int num_blocks = n / L;
        for (int b = 1; b < num_blocks; ++b) {
            int start = b * L;
            int end = (b + 1) * L;
            for (int c = 0; c < 26; ++c) {
                if (pref[c][end] - pref[c][start] != target[c]) {
                    ok = false;
                    break;
                }
            }
            if (!ok) break;
        }

        if (ok) {
            cout << s.substr(0, L) << "\n";
            return 0;
        }
    }

    cout << "*\n";
    return 0;
}
